  }
  for (const event of events) {
    const k = classify(event)
    if (k === undefined) {
      flush()
      out.push(event)
      continue
    }
    const delta = event as DeltaEvent
    const last = run[run.length - 1]
    if (k === kind && last !== undefined && continues(last, delta, k)) {
      // Check that the time gap can be represented exactly: the difference
      // between two safe integers may exceed the exact double range, so
      // subtracting would round and a + (b - a) !== b. Break the run in that
      // case rather than store a gap that cannot reconstruct the original time.
      const gap = delta.time - last.time
      if (Number.isSafeInteger(gap) && last.time + gap === delta.time) {
        run.push(delta)
        continue
      }
    }
    flush()
    kind = k
    run = [delta]
  }
  flush()
  return out
